//! Task-scope normalization, glob matching, and persistence reads.

use super::super::*;

pub(super) fn normalize_paths(paths: &[String]) -> Result<Vec<String>> {
    let mut paths = paths
        .iter()
        .map(|value| value.trim().replace('\\', "/"))
        .filter(|value| !value.is_empty())
        .collect::<Vec<_>>();
    paths.sort();
    paths.dedup();
    for path in &paths {
        compile_scope_glob(path)?;
    }
    Ok(paths)
}

pub(super) fn normalize_symbols(symbols: &[String]) -> Vec<String> {
    let mut symbols = symbols
        .iter()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .collect::<Vec<_>>();
    symbols.sort();
    symbols.dedup();
    symbols
}

pub(super) fn normalize_scope_values(scope: &TaskScope) -> TaskScope {
    let mut paths = scope
        .paths
        .iter()
        .map(|value| value.trim().replace('\\', "/"))
        .filter(|value| !value.is_empty())
        .collect::<Vec<_>>();
    paths.sort();
    paths.dedup();
    let mut symbols = scope
        .symbols
        .iter()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .collect::<Vec<_>>();
    symbols.sort();
    symbols.dedup();
    TaskScope { paths, symbols }
}

pub(super) fn compile_scope_glob(pattern: &str) -> Result<GlobMatcher> {
    GlobBuilder::new(pattern)
        .literal_separator(true)
        .build()
        .map(|glob| glob.compile_matcher())
        .map_err(|error| {
            LodestarError::Invalid(format!("invalid task scope glob '{pattern}': {error}"))
        })
}

pub(in crate::store::coordination) fn task_scope_on(
    connection: &Connection,
    task_id: &str,
) -> Result<TaskScope> {
    let mut statement = connection
        .prepare("SELECT kind, value FROM task_scopes WHERE task_id = ?1 ORDER BY kind, value")?;
    let rows = statement.query_map(params![task_id], |row| {
        Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?))
    })?;
    let mut scope = TaskScope::default();
    for row in rows {
        let (kind, value) = row?;
        match kind.as_str() {
            "path" => scope.paths.push(value),
            "symbol" => scope.symbols.push(value),
            _ => {}
        }
    }
    Ok(scope)
}

pub(in crate::store::coordination) fn intersect_paths(
    requested: &[String],
    declared: &[String],
) -> Result<Vec<String>> {
    let mut matches = Vec::new();
    for request in requested {
        for declaration in declared {
            if compile_scope_glob(declaration)?.is_match(request) {
                matches.push(request.clone());
                break;
            }
        }
    }
    matches.sort();
    matches.dedup();
    Ok(matches)
}
